//! Reading daily bars out of a public CSV, at a DECLARED scale.
//!
//! The shapes are DATA, like the statement profiles: a column layout that changes is a one-line fix
//! rather than a code change, and a file matching nothing is reported rather than half-read.
//!
//! # Why this does not use `money::parse_minor`
//!
//! That function is deliberately fixed at two decimal places and TRUNCATES the rest, because a bank
//! statement is authoritative and inventing a cent from a sub-cent artifact would put a figure in
//! the store that is not on the statement.
//!
//! An adjusted close is the opposite case. `123.456789` is real precision, not an artifact, and
//! truncating every price to `123.45` biases every single one DOWNWARD — which is a systematic
//! distortion of every return computed from them, in the same direction, forever. So bars parse at
//! the scale the series declares, and they ROUND rather than truncate.
use crate::money::{money, Currency, Minor};
use crate::series::{Bar, BarDate, SeriesMeta};

pub use parse_at_scale::parse_at_scale;
pub use format_price::format_price;
pub(crate) use split_line::split_line;

/// One CSV layout. First match wins, so order matters where headers overlap.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BarProfile {
    pub label: &'static str,
    /// Every one of these must be present for the shape to match.
    pub required: &'static [&'static str],
    pub date: &'static str,
    pub open: &'static str,
    pub high: &'static str,
    pub low: &'static str,
    /// The close to USE. For a source carrying both, this is the adjusted one — see `adjusted`.
    pub close: &'static str,
    pub volume: Option<&'static str>,
    /// What the layout lets us assert about adjustment. NONE where the source does not say, which
    /// is not the same as false.
    pub adjusted: Option<bool>,
}

/// The shapes, as data.
///
/// Yahoo's adjusted layout comes FIRST: its file also carries a plain `close`, so a table checking
/// the plain shape first would match it and silently use unadjusted prices from a file that has
/// adjusted ones sitting in the next column.
pub const BAR_PROFILES: &[BarProfile] = &[
    BarProfile {
        label: "yahoo-adjusted",
        required: &["date", "open", "high", "low", "close", "adj close"],
        date: "date",
        open: "open",
        high: "high",
        low: "low",
        close: "adj close",
        volume: Some("volume"),
        adjusted: Some(true),
    },
    BarProfile {
        label: "stooq",
        required: &["date", "open", "high", "low", "close"],
        date: "date",
        open: "open",
        high: "high",
        low: "low",
        close: "close",
        volume: Some("volume"),
        // Stooq's plain download is NOT split-adjusted. Declaring it false is what lets
        // `check_series` flag a split-shaped day as a corporate action rather than a −50% return.
        adjusted: Some(false),
    },
];

#[derive(Debug, Clone, PartialEq)]
pub struct RejectedRow {
    pub line: usize,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ParsedBars {
    pub bars: Vec<Bar>,
    pub meta: SeriesMeta,
    pub profile: &'static str,
    /// Rows that could not be read. NAMED with their line, because a silently short series is a
    /// gap a strategy steps over.
    pub rejected: Vec<RejectedRow>,
}

/// Minor units per whole unit for market data — FOUR decimal places.
///
/// Two is not enough: adjusted closes routinely carry more, and rounding them to cents turns a
/// long-run adjusted series into a staircase. Declared on the series so nothing can mix a price at
/// this scale with an account balance at cents.
pub const MARKET_SCALE: i64 = 10_000;

/// Read a CSV of daily bars.
///
/// The symbol and the source are CALLER-supplied, because a file does not know either — and
/// `SeriesMeta` is the place where what nobody declared stays undeclared.
pub fn parse_csv(text: &str, symbol: &str, source: &str) -> Result<ParsedBars, String> {
    let lines: Vec<&str> = text.lines().filter(|l| !l.trim().is_empty()).collect();
    let header_line = lines.first().ok_or("the file is empty")?;
    let header: Vec<String> = split_line(header_line).iter().map(|h| h.to_lowercase()).collect();
    let at = |name: &str| header.iter().position(|h| h == name);

    let profile = BAR_PROFILES
        .iter()
        .find(|p| p.required.iter().all(|r| header.contains(&r.to_string())))
        .ok_or_else(|| {
            format!(
                "no bar layout matches these columns: {}. Known layouts: {}",
                header.join(", "),
                BAR_PROFILES.iter().map(|p| p.label).collect::<Vec<_>>().join(", ")
            )
        })?;

    let (di, oi, hi, li, ci) = (
        at(profile.date).ok_or("no date column")?,
        at(profile.open).ok_or("no open column")?,
        at(profile.high).ok_or("no high column")?,
        at(profile.low).ok_or("no low column")?,
        at(profile.close).ok_or("no close column")?,
    );
    let vi = profile.volume.and_then(at);

    let mut bars: Vec<Bar> = Vec::new();
    let mut rejected: Vec<RejectedRow> = Vec::new();
    for (n, line) in lines.iter().enumerate().skip(1) {
        let cells = split_line(line);
        let get = |i: usize| cells.get(i).map(String::as_str).unwrap_or("");
        let date = get(di).to_string();
        if date.len() < 10 {
            rejected.push(RejectedRow { line: n + 1, reason: format!("{date:?} is not a YYYY-MM-DD date") });
            continue;
        }
        let prices: Result<Vec<Minor>, String> = [oi, hi, li, ci].iter().map(|i| parse_at_scale(get(*i), MARKET_SCALE)).collect();
        match prices {
            Err(e) => rejected.push(RejectedRow { line: n + 1, reason: e }),
            Ok(p) => bars.push(Bar {
                date_i: BarDate::new(&date[..10]),
                open: money(p[0], Currency::USD),
                high: money(p[1], Currency::USD),
                low: money(p[2], Currency::USD),
                close: money(p[3], Currency::USD),
                // ABSENT where the source did not carry it, never zero — a volume filter reading
                // zero as "no trading" would silently drop every bar of an otherwise fine series.
                volume: vi.and_then(|i| get(i).replace(',', "").parse::<i64>().ok()),
            }),
        }
    }

    Ok(ParsedBars {
        meta: SeriesMeta {
            symbol: symbol.to_string(),
            adjusted: profile.adjusted,
            // NOBODY DECLARED IT, and it cannot be inferred from one instrument's file. Left None
            // so `may_make_universe_claim` refuses rather than a universe claim being made by
            // accident from a single-name backtest.
            survivorship_free: None,
            source: source.to_string(),
            minor_per_unit: MARKET_SCALE,
        },
        profile: profile.label,
        bars,
        rejected,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_price_is_rounded_at_the_declared_scale_and_never_truncated() {
        // The whole reason this is not `money::parse_minor`: truncation moves every price the same
        // direction, so it does not cancel over a series the way rounding does.
        assert_eq!(parse_at_scale("123.45", MARKET_SCALE).unwrap(), 1_234_500);
        assert_eq!(parse_at_scale("123.456789", MARKET_SCALE).unwrap(), 1_234_568, "rounded UP, not truncated to ...67");
        assert_eq!(parse_at_scale("123.456712", MARKET_SCALE).unwrap(), 1_234_567);
        assert_eq!(parse_at_scale("0.00005", MARKET_SCALE).unwrap(), 1, "a half at the boundary rounds away from zero");
        assert_eq!(parse_at_scale("123", MARKET_SCALE).unwrap(), 1_230_000);
        assert_eq!(parse_at_scale("-1.5", MARKET_SCALE).unwrap(), -15_000);
        assert_eq!(parse_at_scale("1,234.50", MARKET_SCALE).unwrap(), 12_345_000, "thousands separators carry no value");
        // At cents, the same string is a different number of minor units — which is exactly why the
        // scale is DECLARED on the series rather than assumed.
        assert_eq!(parse_at_scale("123.45", 100).unwrap(), 12_345);
    }

    #[test]
    fn an_unreadable_price_is_refused_rather_than_guessed() {
        assert!(parse_at_scale("", MARKET_SCALE).is_err());
        assert!(parse_at_scale("  ", MARKET_SCALE).is_err());
        assert!(parse_at_scale("N/A", MARKET_SCALE).is_err());
        assert!(parse_at_scale("1.2.3", MARKET_SCALE).is_err());
        assert!(parse_at_scale("null", MARKET_SCALE).is_err());
    }

    #[test]
    fn the_adjusted_layout_wins_because_the_file_carries_both_closes() {
        // Yahoo's file has `close` AND `adj close`. A table checking the plain shape first would
        // match it and silently backtest unadjusted prices sitting next to adjusted ones.
        let csv = "Date,Open,High,Low,Close,Adj Close,Volume\n2026-06-01,10.00,10.50,9.90,10.40,5.20,1000\n";
        let p = parse_csv(csv, "ACME", "yahoo").expect("parses");
        assert_eq!(p.profile, "yahoo-adjusted");
        assert_eq!(p.meta.adjusted, Some(true));
        assert_eq!(p.bars[0].close.minor, 52_000, "the ADJUSTED close, not the 10.40");
        assert_eq!(p.bars[0].volume, Some(1_000));
    }

    #[test]
    fn stooq_declares_itself_unadjusted_so_a_split_is_flagged_rather_than_traded() {
        let csv = "Date,Open,High,Low,Close,Volume\n2026-06-01,10.00,10.50,9.90,10.40,1000\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.profile, "stooq");
        // Declaring FALSE is what lets `check_series` call a −50% day a corporate action. Leaving
        // it undeclared would let a strategy that buys drops find a great many of them.
        assert_eq!(p.meta.adjusted, Some(false));
        assert_eq!(p.bars[0].close.minor, 104_000);
    }

    #[test]
    fn survivorship_is_left_undeclared_because_one_files_worth_of_data_cannot_know() {
        let csv = "Date,Open,High,Low,Close,Volume\n2026-06-01,10,10,10,10,1\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.meta.survivorship_free, None);
        // So a universe claim from it is refused, which is the point — a single-name file says
        // nothing about what is missing from a universe.
        let s = crate::series::unverified_series(&p.bars, p.meta, "test").expect("caveat");
        assert!(!crate::series::may_make_universe_claim(&s).allowed);
    }

    #[test]
    fn an_unreadable_row_is_named_with_its_line_rather_than_dropped() {
        let csv = "Date,Open,High,Low,Close\n2026-06-01,10,10,10,10\n2026-06-02,N/A,10,10,10\nbad-date,1,1,1,1\n2026-06-03,11,11,11,11\n";
        let p = parse_csv(csv, "ACME", "stooq").expect("parses");
        assert_eq!(p.bars.len(), 2);
        assert_eq!(p.rejected.len(), 2);
        assert_eq!(p.rejected[0].line, 3);
        assert_eq!(p.rejected[1].line, 4);
        assert!(p.rejected[1].reason.contains("not a YYYY-MM-DD date"));
        // A silently short series is a gap a strategy steps over without noticing, so the count is
        // reported rather than the rows just being absent.
    }

    #[test]
    fn a_file_matching_no_layout_is_refused_and_says_what_it_knows() {
        let e = parse_csv("Ticker,Price\nACME,10\n", "ACME", "x").unwrap_err();
        assert!(e.contains("no bar layout matches"));
        assert!(e.contains("yahoo-adjusted") && e.contains("stooq"), "it names the layouts it does know");
        assert!(parse_csv("", "ACME", "x").is_err());
    }

    #[test]
    fn a_price_renders_back_at_its_own_scale() {
        let p = parse_csv("Date,Open,High,Low,Close\n2026-06-01,123.4567,1,1,1\n", "ACME", "stooq").expect("parses");
        assert_eq!(format_price(p.bars[0].open, &p.meta), "123.4567");
        let cents = SeriesMeta { minor_per_unit: 100, ..p.meta.clone() };
        assert_eq!(format_price(money(12_345, Currency::USD), &cents), "123.45");
    }
}
